dashboard.definition:
{
  "title": "Advanced Dashboard",
  "description": "Cross-quiz analytics. Filter by time, quiz, session and nickname.",
  "defaults": {
    "visualizations": {
      "global": {
        "showProgressBar": true,
        "showLastUpdated": false
      }
    }
  },
  "dataSources": {
    "ds_input_quiz": {
      "type": "ds.search",
      "name": "Quiz dropdown",
      "options": {
        "query": "`ponypoll_index` sourcetype=ponypoll_attempt | stats first(quiz_name) as quiz_name by quiz_id\n| eval label=if(isnotnull(quiz_name) AND quiz_name!=\"\", quiz_name, quiz_id) | fields quiz_id label | sort label",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_input_session": {
      "type": "ds.search",
      "name": "Session dropdown",
      "options": {
        "query": "`ponypoll_index` sourcetype=ponypoll_answer session_name=* | stats max(_time) as last_event by session_name | sort -last_event | fields session_name",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_completions": {
      "type": "ds.search",
      "name": "Completions",
      "options": {
        "query": "`ponypoll_index` sourcetype=ponypoll_attempt event=quiz_complete\n            (\"$quiz_tok$\"=\"*\" OR quiz_id=\"$quiz_tok$\")\n            (\"$session_tok$\"=\"*\" OR session_name=\"$session_tok$\")\n            (\"$nickname_tok$\"=\"*\" OR nickname=\"$nickname_tok$\")\n            | stats count",
        "queryParameters": {
          "earliest": "$tr.earliest$",
          "latest": "$tr.latest$"
        }
      }
    },
    "ds_players": {
      "type": "ds.search",
      "name": "Players",
      "options": {
        "query": "`ponypoll_index` sourcetype=ponypoll_attempt event=quiz_complete\n            (\"$quiz_tok$\"=\"*\" OR quiz_id=\"$quiz_tok$\")\n            (\"$session_tok$\"=\"*\" OR session_name=\"$session_tok$\")\n            (\"$nickname_tok$\"=\"*\" OR nickname=\"$nickname_tok$\")\n            | stats dc(nickname) as players",
        "queryParameters": {
          "earliest": "$tr.earliest$",
          "latest": "$tr.latest$"
        }
      }
    },
    "ds_accuracy": {
      "type": "ds.search",
      "name": "Accuracy",
      "options": {
        "query": "`ponypoll_index` sourcetype=ponypoll_answer\n            (\"$quiz_tok$\"=\"*\" OR quiz_id=\"$quiz_tok$\")\n            (\"$session_tok$\"=\"*\" OR session_name=\"$session_tok$\")\n            (\"$nickname_tok$\"=\"*\" OR nickname=\"$nickname_tok$\")\n            | eval c=if(correct=\"true\",1,0) | stats avg(c) as accuracy | eval accuracy=round(accuracy*100,1)",
        "queryParameters": {
          "earliest": "$tr.earliest$",
          "latest": "$tr.latest$"
        }
      }
    },
    "ds_avg_score": {
      "type": "ds.search",
      "name": "Avg score",
      "options": {
        "query": "`ponypoll_index` sourcetype=ponypoll_attempt event=quiz_complete\n            (\"$quiz_tok$\"=\"*\" OR quiz_id=\"$quiz_tok$\")\n            (\"$session_tok$\"=\"*\" OR session_name=\"$session_tok$\")\n            (\"$nickname_tok$\"=\"*\" OR nickname=\"$nickname_tok$\")\n            | stats avg(total_score) as avg_score | eval avg_score=round(avg_score,0)",
        "queryParameters": {
          "earliest": "$tr.earliest$",
          "latest": "$tr.latest$"
        }
      }
    },
    "ds_avg_used": {
      "type": "ds.search",
      "name": "Avg sec used",
      "options": {
        "query": "`ponypoll_index` sourcetype=ponypoll_answer\n            (\"$quiz_tok$\"=\"*\" OR quiz_id=\"$quiz_tok$\")\n            (\"$session_tok$\"=\"*\" OR session_name=\"$session_tok$\")\n            (\"$nickname_tok$\"=\"*\" OR nickname=\"$nickname_tok$\")\n            | eval timer=coalesce(tonumber(time_limit), tonumber(timeLimit), 30)\n            | eval seconds_used=round(timer-tonumber(time_remaining),1)\n            | eval seconds_used=if(seconds_used<0,0,seconds_used)\n            | stats avg(seconds_used) as avg_used | eval avg_used=round(avg_used,1)",
        "queryParameters": {
          "earliest": "$tr.earliest$",
          "latest": "$tr.latest$"
        }
      }
    },
    "ds_finish": {
      "type": "ds.search",
      "name": "Finish rate",
      "options": {
        "query": "`ponypoll_index` sourcetype=ponypoll_attempt\n            (\"$quiz_tok$\"=\"*\" OR quiz_id=\"$quiz_tok$\")\n            (\"$session_tok$\"=\"*\" OR session_name=\"$session_tok$\")\n            (\"$nickname_tok$\"=\"*\" OR nickname=\"$nickname_tok$\")\n            | eval is_start=if(event=\"quiz_start\",1,0), is_done=if(event=\"quiz_complete\",1,0)\n            | stats sum(is_start) as starts sum(is_done) as dones | eval rate=if(starts>0, round(100*dones/starts,1), 0) | fields rate",
        "queryParameters": {
          "earliest": "$tr.earliest$",
          "latest": "$tr.latest$"
        }
      }
    },
    "ds_sankey": {
      "type": "ds.search",
      "name": "Sankey",
      "options": {
        "query": "`ponypoll_index` sourcetype=ponypoll_answer\n            (\"$quiz_tok$\"=\"*\" OR quiz_id=\"$quiz_tok$\")\n            (\"$session_tok$\"=\"*\" OR session_name=\"$session_tok$\")\n            (\"$nickname_tok$\"=\"*\" OR nickname=\"$nickname_tok$\")\n            | eval timer=coalesce(tonumber(time_limit), tonumber(timeLimit), 30)\n            | eval seconds_used=round(timer-tonumber(time_remaining),1)\n            | eval seconds_used=if(seconds_used<0,0,seconds_used)\n            | eval type=if(isnull(type) OR type=\"\",\"unknown\",type)\n            | eval speed=case(seconds_used<=8,\"Fast\", seconds_used<=16,\"Medium\", true(),\"Slow\")\n            | eval result=if(correct=\"true\",\"Correct\",\"Wrong\")\n            | eval from=type, to=speed | appendpipe [| eval from=speed, to=result]\n            | stats count as count by from to | where isnotnull(from) AND isnotnull(to)",
        "queryParameters": {
          "earliest": "$tr.earliest$",
          "latest": "$tr.latest$"
        }
      }
    },
    "ds_speed_hist": {
      "type": "ds.search",
      "name": "Speed hist",
      "options": {
        "query": "`ponypoll_index` sourcetype=ponypoll_answer\n            (\"$quiz_tok$\"=\"*\" OR quiz_id=\"$quiz_tok$\")\n            (\"$session_tok$\"=\"*\" OR session_name=\"$session_tok$\")\n            (\"$nickname_tok$\"=\"*\" OR nickname=\"$nickname_tok$\")\n            | eval timer=coalesce(tonumber(time_limit), tonumber(timeLimit), 30)\n            | eval seconds_used=round(timer-tonumber(time_remaining),1)\n            | eval seconds_used=if(seconds_used<0,0,seconds_used)\n            | eval used=floor(seconds_used/2)*2 | eval result=if(correct=\"true\",\"Correct\",\"Wrong\")\n            | chart count by used result | sort used | rename used as \"Seconds used\"",
        "queryParameters": {
          "earliest": "$tr.earliest$",
          "latest": "$tr.latest$"
        }
      }
    },
    "ds_speed_outcome": {
      "type": "ds.search",
      "name": "Speed outcome",
      "options": {
        "query": "`ponypoll_index` sourcetype=ponypoll_answer\n            (\"$quiz_tok$\"=\"*\" OR quiz_id=\"$quiz_tok$\")\n            (\"$session_tok$\"=\"*\" OR session_name=\"$session_tok$\")\n            (\"$nickname_tok$\"=\"*\" OR nickname=\"$nickname_tok$\")\n            | eval timer=coalesce(tonumber(time_limit), tonumber(timeLimit), 30)\n            | eval seconds_used=round(timer-tonumber(time_remaining),1)\n            | eval seconds_used=if(seconds_used<0,0,seconds_used)\n            | eval result=if(correct=\"true\",\"Correct\",\"Wrong\")\n            | chart avg(seconds_used) as avg_sec_used, median(seconds_used) as median_sec_used by result\n            | eval avg_sec_used=round(avg_sec_used,1), median_sec_used=round(median_sec_used,1)\n            | rename result as Outcome, avg_sec_used as \"Avg sec used\", median_sec_used as \"Median sec used\"",
        "queryParameters": {
          "earliest": "$tr.earliest$",
          "latest": "$tr.latest$"
        }
      }
    },
    "ds_speed_acc": {
      "type": "ds.search",
      "name": "Speed acc",
      "options": {
        "query": "`ponypoll_index` sourcetype=ponypoll_answer\n            (\"$quiz_tok$\"=\"*\" OR quiz_id=\"$quiz_tok$\")\n            (\"$session_tok$\"=\"*\" OR session_name=\"$session_tok$\")\n            (\"$nickname_tok$\"=\"*\" OR nickname=\"$nickname_tok$\")\n            | eval timer=coalesce(tonumber(time_limit), tonumber(timeLimit), 30)\n            | eval seconds_used=round(timer-tonumber(time_remaining),1)\n            | eval seconds_used=if(seconds_used<0,0,seconds_used)\n            | eval speed=case(seconds_used<=8,\"Fast\", seconds_used<=16,\"Medium\", true(),\"Slow\")\n            | eval c=if(correct=\"true\",1,0) | eval ord=case(speed=\"Fast\",1, speed=\"Medium\",2, true(),3)\n            | stats avg(c) as pct count as Answers by speed ord | eval pct=round(pct*100,1) | sort ord\n            | rename speed as Speed, pct as \"Accuracy %\" | table Speed \"Accuracy %\" Answers",
        "queryParameters": {
          "earliest": "$tr.earliest$",
          "latest": "$tr.latest$"
        }
      }
    },
    "ds_score_bands": {
      "type": "ds.search",
      "name": "Score bands",
      "options": {
        "query": "`ponypoll_index` sourcetype=ponypoll_attempt event=quiz_complete\n            (\"$quiz_tok$\"=\"*\" OR quiz_id=\"$quiz_tok$\")\n            (\"$session_tok$\"=\"*\" OR session_name=\"$session_tok$\")\n            (\"$nickname_tok$\"=\"*\" OR nickname=\"$nickname_tok$\")\n            | eval band=floor(total_score/1000)*1000 | eval Score=band.\"–\".(band+999)\n            | stats count as Runs by Score band | sort band | fields Score Runs",
        "queryParameters": {
          "earliest": "$tr.earliest$",
          "latest": "$tr.latest$"
        }
      }
    },
    "ds_type_acc": {
      "type": "ds.search",
      "name": "Type acc",
      "options": {
        "query": "`ponypoll_index` sourcetype=ponypoll_answer\n            (\"$quiz_tok$\"=\"*\" OR quiz_id=\"$quiz_tok$\")\n            (\"$session_tok$\"=\"*\" OR session_name=\"$session_tok$\")\n            (\"$nickname_tok$\"=\"*\" OR nickname=\"$nickname_tok$\")\n            | eval c=if(correct=\"true\",1,0) | stats avg(c) as pct count as Answers by type\n            | eval pct=round(pct*100,1) | rename type as Type, pct as \"Accuracy %\" | sort \"Accuracy %\" | table Type \"Accuracy %\" Answers",
        "queryParameters": {
          "earliest": "$tr.earliest$",
          "latest": "$tr.latest$"
        }
      }
    },
    "ds_sessions": {
      "type": "ds.search",
      "name": "Sessions",
      "options": {
        "query": "`ponypoll_index` sourcetype=ponypoll_answer\n            (\"$quiz_tok$\"=\"*\" OR quiz_id=\"$quiz_tok$\")\n            (\"$session_tok$\"=\"*\" OR session_name=\"$session_tok$\")\n            (\"$nickname_tok$\"=\"*\" OR nickname=\"$nickname_tok$\")\n            | eval timer=coalesce(tonumber(time_limit), tonumber(timeLimit), 30)\n            | eval seconds_used=round(timer-tonumber(time_remaining),1)\n            | eval seconds_used=if(seconds_used<0,0,seconds_used)\n            | eval c=if(correct=\"true\",1,0)\n            | stats count as Answers dc(nickname) as Players avg(c) as Acc avg(seconds_used) as avg_used by session_name\n            | eval Acc=round(Acc*100,1), avg_used=round(avg_used,1)\n            | rename session_name as Session, avg_used as \"Avg sec used\" | sort -Acc | table Session Players Answers Acc \"Avg sec used\"",
        "queryParameters": {
          "earliest": "$tr.earliest$",
          "latest": "$tr.latest$"
        }
      }
    },
    "ds_leaderboard": {
      "type": "ds.search",
      "name": "History LB",
      "options": {
        "query": "`ponypoll_index` sourcetype=ponypoll_attempt event=quiz_complete\n            (\"$quiz_tok$\"=\"*\" OR quiz_id=\"$quiz_tok$\")\n            (\"$session_tok$\"=\"*\" OR session_name=\"$session_tok$\")\n            (\"$nickname_tok$\"=\"*\" OR nickname=\"$nickname_tok$\")\n            | stats max(total_score) as best_score count as runs avg(total_score) as avg_score by nickname\n            | eval avg_score=round(avg_score,0) | sort -best_score | head 20 | streamstats count as rank\n            | eval \"#\"=tostring(rank) | rename nickname as Player, best_score as \"Best score\", avg_score as \"Avg score\", runs as Runs\n            | table \"#\" Player \"Best score\" \"Avg score\" Runs",
        "queryParameters": {
          "earliest": "$tr.earliest$",
          "latest": "$tr.latest$"
        }
      }
    },
    "ds_lb_chart": {
      "type": "ds.chain",
      "name": "History LB chart",
      "options": {
        "extend": "ds_leaderboard",
        "query": "| fields Player \"Best score\" | sort -\"Best score\" | head 10"
      }
    },
    "ds_difficulty": {
      "type": "ds.search",
      "name": "Difficulty",
      "options": {
        "query": "`ponypoll_index` sourcetype=ponypoll_answer\n            (\"$quiz_tok$\"=\"*\" OR quiz_id=\"$quiz_tok$\")\n            (\"$session_tok$\"=\"*\" OR session_name=\"$session_tok$\")\n            (\"$nickname_tok$\"=\"*\" OR nickname=\"$nickname_tok$\")\n            | eval timer=coalesce(tonumber(time_limit), tonumber(timeLimit), 30)\n            | eval seconds_used=round(timer-tonumber(time_remaining),1)\n            | eval seconds_used=if(seconds_used<0,0,seconds_used)\n            | eval correct_int=if(correct=\"true\",1,0)\n            | stats count as Total sum(correct_int) as Correct avg(seconds_used) as avg_used avg(points) as avg_pts by question\n            | eval Wrong=Total-Correct, pct_correct=round(Correct/Total*100,1), avg_used=round(avg_used,1), avg_pts=round(avg_pts,0)\n            | rename question as Question, pct_correct as \"% Correct\", avg_used as \"Avg sec used\", avg_pts as \"Avg pts\"\n            | table Question \"% Correct\" Correct Wrong \"Avg sec used\" \"Avg pts\" | sort \"% Correct\"",
        "queryParameters": {
          "earliest": "$tr.earliest$",
          "latest": "$tr.latest$"
        }
      }
    },
    "ds_difficulty_chart": {
      "type": "ds.chain",
      "name": "Difficulty chart",
      "options": {
        "extend": "ds_difficulty",
        "query": "| fields Question \"% Correct\" | sort \"% Correct\""
      }
    },
    "ds_missed": {
      "type": "ds.search",
      "name": "Missed",
      "options": {
        "query": "`ponypoll_index` sourcetype=ponypoll_answer\n            (\"$quiz_tok$\"=\"*\" OR quiz_id=\"$quiz_tok$\")\n            (\"$session_tok$\"=\"*\" OR session_name=\"$session_tok$\")\n            (\"$nickname_tok$\"=\"*\" OR nickname=\"$nickname_tok$\") correct=\"false\"\n            | stats count as Misses by question, answer | sort -Misses | head 15\n            | rename question as Question, answer as \"Given answer\" | table Misses Question \"Given answer\"",
        "queryParameters": {
          "earliest": "$tr.earliest$",
          "latest": "$tr.latest$"
        }
      }
    },
    "ds_scatter": {
      "type": "ds.search",
      "name": "Scatter",
      "options": {
        "query": "`ponypoll_index` sourcetype=ponypoll_answer\n            (\"$quiz_tok$\"=\"*\" OR quiz_id=\"$quiz_tok$\")\n            (\"$session_tok$\"=\"*\" OR session_name=\"$session_tok$\")\n            (\"$nickname_tok$\"=\"*\" OR nickname=\"$nickname_tok$\")\n            | eval timer=coalesce(tonumber(time_limit), tonumber(timeLimit), 30)\n            | eval seconds_used=round(timer-tonumber(time_remaining),1)\n            | eval seconds_used=if(seconds_used<0,0,seconds_used)\n            | eval c=if(correct=\"true\",1,0)\n            | stats avg(c) as accuracy avg(seconds_used) as avg_used count as answers by nickname\n            | eval accuracy=round(accuracy*100,1), avg_used=round(avg_used,1)\n            | rename nickname as Player, accuracy as accuracy_pct | table Player avg_used accuracy_pct answers",
        "queryParameters": {
          "earliest": "$tr.earliest$",
          "latest": "$tr.latest$"
        }
      }
    },
    "ds_input_nickname": {
      "type": "ds.search",
      "name": "Nickname dropdown",
      "options": {
        "query": "`ponypoll_index` sourcetype=ponypoll_attempt event=quiz_complete\n            (\"$quiz_tok$\"=\"*\" OR quiz_id=\"$quiz_tok$\")\n            (\"$session_tok$\"=\"*\" OR session_name=\"$session_tok$\")\n            | stats count by nickname | sort nickname",
        "queryParameters": {
          "earliest": "$tr.earliest$",
          "latest": "$tr.latest$"
        }
      }
    }
  },
  "inputs": {
    "input_tr": {
      "type": "input.timerange",
      "title": "Time",
      "options": {
        "token": "tr",
        "defaultValue": "-7d@d,now"
      }
    },
    "input_quiz": {
      "type": "input.dropdown",
      "title": "Quiz",
      "options": {
        "token": "quiz_tok",
        "defaultValue": "*",
        "items": [
          {
            "label": "All quizzes",
            "value": "*"
          }
        ]
      },
      "dataSources": {
        "primary": "ds_input_quiz"
      },
      "encoding": {
        "label": "primary.label",
        "value": "primary.quiz_id"
      }
    },
    "input_session": {
      "type": "input.dropdown",
      "title": "Session",
      "options": {
        "token": "session_tok",
        "defaultValue": "*",
        "items": [
          {
            "label": "All sessions",
            "value": "*"
          }
        ]
      },
      "dataSources": {
        "primary": "ds_input_session"
      },
      "encoding": {
        "label": "primary.session_name",
        "value": "primary.session_name"
      }
    },
    "input_nickname": {
      "type": "input.dropdown",
      "title": "Nickname",
      "options": {
        "token": "nickname_tok",
        "defaultValue": "*",
        "items": [
          {
            "label": "All players",
            "value": "*"
          }
        ]
      },
      "dataSources": {
        "primary": "ds_input_nickname"
      },
      "encoding": {
        "label": "primary.nickname",
        "value": "primary.nickname"
      }
    }
  },
  "visualizations": {
    "viz_h_completions": {
      "type": "splunk.singlevalue",
      "title": "Completions",
      "dataSources": {
        "primary": "ds_completions"
      },
      "options": {
        "majorColor": "#00A4EF",
        "numberPrecision": 0,
        "backgroundColor": "#141922",
        "majorFontSize": 36
      }
    },
    "viz_h_players": {
      "type": "splunk.singlevalue",
      "title": "Players",
      "dataSources": {
        "primary": "ds_players"
      },
      "options": {
        "majorColor": "#5CC05C",
        "numberPrecision": 0,
        "backgroundColor": "#141922",
        "majorFontSize": 36
      }
    },
    "viz_h_accuracy": {
      "type": "splunk.singlevalueradial",
      "title": "Accuracy",
      "dataSources": {
        "primary": "ds_accuracy"
      },
      "options": {
        "majorColor": "#5CC05C",
        "numberPrecision": 1,
        "backgroundColor": "#141922",
        "majorFontSize": 28,
        "unit": "%",
        "unitPosition": "after"
      }
    },
    "viz_h_avg_score": {
      "type": "splunk.singlevalue",
      "title": "Avg score",
      "dataSources": {
        "primary": "ds_avg_score"
      },
      "options": {
        "majorColor": "#F5A623",
        "numberPrecision": 0,
        "backgroundColor": "#141922",
        "majorFontSize": 36
      }
    },
    "viz_h_avg_used": {
      "type": "splunk.singlevalue",
      "title": "Avg sec used",
      "dataSources": {
        "primary": "ds_avg_used"
      },
      "options": {
        "majorColor": "#ED8B00",
        "numberPrecision": 1,
        "backgroundColor": "#141922",
        "majorFontSize": 36,
        "unit": "s",
        "unitPosition": "after"
      }
    },
    "viz_h_finish": {
      "type": "splunk.singlevalueradial",
      "title": "Finish rate",
      "dataSources": {
        "primary": "ds_finish"
      },
      "options": {
        "majorColor": "#00A4EF",
        "numberPrecision": 1,
        "backgroundColor": "#141922",
        "majorFontSize": 28,
        "unit": "%",
        "unitPosition": "after"
      }
    },
    "viz_h_sankey": {
      "type": "splunk.sankey",
      "title": "Type → speed → correct / wrong",
      "description": "Fast ≤8s used, Medium 9–16s, Slow >16s.",
      "dataSources": {
        "primary": "ds_sankey"
      },
      "options": {
        "backgroundColor": "#141922",
        "linksSourceField": "from",
        "linksTargetField": "to",
        "linksValueField": "count"
      },
      "encoding": {
        "from": "primary.from",
        "to": "primary.to",
        "value": "primary.count",
        "source": "primary.from",
        "target": "primary.to"
      }
    },
    "viz_h_speed_hist": {
      "type": "splunk.column",
      "title": "Seconds used vs correct / wrong",
      "dataSources": {
        "primary": "ds_speed_hist"
      },
      "options": {
        "backgroundColor": "#141922",
        "legendDisplay": "right",
        "seriesColors": [
          "#5CC05C",
          "#E06C75"
        ],
        "yAxisTitleText": "Answers",
        "xAxisTitleText": "Seconds used",
        "dataValuesDisplay": "off",
        "stackMode": "stacked"
      }
    },
    "viz_h_speed_outcome": {
      "type": "splunk.column",
      "title": "Avg / median seconds used",
      "dataSources": {
        "primary": "ds_speed_outcome"
      },
      "options": {
        "backgroundColor": "#141922",
        "legendDisplay": "right",
        "seriesColors": [
          "#00A4EF",
          "#F5A623"
        ],
        "yAxisTitleText": "Seconds used",
        "xAxisTitleText": "",
        "dataValuesDisplay": "all"
      }
    },
    "viz_h_speed_acc": {
      "type": "splunk.bar",
      "title": "Accuracy by speed",
      "dataSources": {
        "primary": "ds_speed_acc"
      },
      "options": {
        "backgroundColor": "#141922",
        "legendDisplay": "off",
        "seriesColors": [
          "#5CC05C"
        ],
        "yAxisTitleText": "Accuracy %",
        "xAxisTitleText": "",
        "dataValuesDisplay": "all"
      }
    },
    "viz_h_bands": {
      "type": "splunk.column",
      "title": "Score distribution",
      "dataSources": {
        "primary": "ds_score_bands"
      },
      "options": {
        "backgroundColor": "#141922",
        "legendDisplay": "off",
        "seriesColors": [
          "#00A4EF"
        ],
        "yAxisTitleText": "Runs",
        "xAxisTitleText": "Score band",
        "dataValuesDisplay": "all"
      }
    },
    "viz_h_type_acc": {
      "type": "splunk.bar",
      "title": "Accuracy by question type",
      "dataSources": {
        "primary": "ds_type_acc"
      },
      "options": {
        "backgroundColor": "#141922",
        "legendDisplay": "off",
        "seriesColors": [
          "#5CC05C"
        ],
